#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const int MOD = 1000000007;
const int N = 1000000 + 7;

ll pw(ll x, ll k) {
    ll result = 1;
    x %= MOD;
    while (k > 0) {
        if (k & 1) result = result * x % MOD;
        x = x * x % MOD;
        k >>= 1;
    }
    return result;
}

ll get(ll x, ll k, ll mod) {
    ll result = 1 % mod;
    x %= mod;
    while (k > 0) {
        if (k & 1) result = result * x % mod;
        x = x * x % mod;
        k >>= 1;
    }
    return result;
}

int n, k;
int a[N];
bool check[N];

void solve() {
    cin >> n >> k;

    if (n == 0) {
        cout << pw(k, k - 1);
        return;
    }
    if (n == 1) {
        cout << pw(k, k);
        return;
    }

    for (int d = 0; d < n; ++d) {
        a[d] = static_cast<ll>(d) * k % n;
    }

    ll ans = 1;
    for (int d = 0; d < n; ++d) {
        if (check[d]) continue;

        int cur = d;
        int cnt = 0;
        do {
            check[cur] = true;
            cur = a[cur];
            ++cnt;
        } while (!check[cur]);

        if (get(k, cnt, n) == 1) {
            ans = ans * n % MOD;
        }
    }

    cout << ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    solve();
    return 0;
}

