using namespace std;

using ll = long long;

const int MOD = 1'000'000'007;

ll modPow(ll base, ll exp, ll mod) {
    ll result = 1 % mod;
    base %= mod;
    while (exp > 0) {
        if (exp & 1LL) result = result * base % mod;
        base = base * base % mod;
        exp >>= 1LL;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    if (k == 0) {
        cout << modPow(n, n - 1, MOD);
        return 0;
    }

    if (k == 1) {
        cout << modPow(n, n, MOD);
        return 0;
    }

    vector<unsigned char> visited(n, 0);
    ll answer = 1;

    for (int start = 0; start < n; ++start) {
        if (visited[start]) continue;

        int current = start;
        int count = 0;

        while (!visited[current]) {
            visited[current] = 1;
            current = static_cast<ll>(current) * k % n;
            ++count;
        }

        if (modPow(k, count, n) == 1) {
            answer = answer * n % MOD;
        }
    }

    cout << answer;
    return 0;
}

